/**
 * sheetsProvider.js
 * ───────────────────
 * Stores contact-form enquiries in Google Sheets (tab: "Enquiries").
 * Replaces supabaseProvider.js entirely.
 *
 * The row's `id` is generated by sheetsDb.insert() (short, readable,
 * sequential — e.g. "EQ-SITE-004"), NOT passed in here.
 */

const sheetsDb = require('../sheetsDb');

const TAB = 'Enquiries';

async function save(record) {
  const row = {
    first_name  : record.firstName,
    last_name   : record.lastName,
    company     : record.company,
    email       : record.email,
    country_code: record.countryCode,
    phone       : record.phone,
    reason      : record.reason,
    message     : record.message,
    // "SMS" column — YES if the visitor checked the SMS-consent box on
    // the Contact form, NO otherwise.
    sms         : record.smsConsent ? 'YES' : 'NO',
    status      : record.status || 'new',
    source      : record.source || 'website_form',
    admin_notes : '',
  };

  const saved = await sheetsDb.insert(TAB, row);
  console.log(`[Sheets] Saved enquiry ${saved.id}`);
  return { id: saved.id };
}

async function validate() {
  await sheetsDb.validateTabs([TAB]);
  console.log('[Sheets] Enquiries tab validated ✓');
}

module.exports = { save, validate };